mapper.select:
SELECT EFT.TRANSFER_ID, EFT.APPLY_NUMBER, EFT.COMPANY_ID, EFT.UNIT_ID, EFT.DATA_CLASS, EFT.APPLY_STATUS, v1.meaning APPLY_STATUS_N, EFT.APPLY_DATE, EFT.BUSINESS_TYPE, EFT.DESCRIPTION, FOU.UNIT_NAME, EFT.REF_TRANSFER_ID, FC.COMPANY_FULL_NAME COMPANY_NAME, SU.DESCRIPTION APPLY_USER_NAME FROM EFT_FUND_TRANSFER EFT JOIN FND_ORG_UNIT FOU ON FOU.UNIT_ID=EFT.UNIT_ID JOIN FND_COMPANY FC ON FC.COMPANY_ID=EFT.COMPANY_ID JOIN SYS_USER SU ON SU.USER_ID=EFT.CREATED_BY left join sys_code_value_b_v v1 on v1.code_value = EFT.APPLY_STATUS and v1.code = 'HLS.WORK_FLOW_STATUS' WHERE 1=1
AND EFT.TRANSFER_ID = #{transferId}
AND EFT.COMPANY_ID = #{request.companyId}
AND EFT.DATA_CLASS = #{dataClass}
AND EFT.BUSINESS_TYPE = #{businessType}
AND EFT.APPLY_DATE >= #{applyDateStart}
AND EFT.APPLY_DATE <= #{applyDateEnd}
AND EFT.APPLY_STATUS = #{applyStatus}
AND SU.DESCRIPTION LIKE CONCAT(CONCAT('%',#{applyUserName}),'%')
ORDER BY ( CASE WHEN EFT.APPLY_STATUS='NEW' THEN 1 WHEN EFT.APPLY_STATUS='APPROVED_RETURN' THEN 2 WHEN EFT.APPLY_STATUS='APPROVING' THEN 3 WHEN EFT.APPLY_STATUS='APPROVED' THEN 4 END ) , EFT.APPLY_DATE DESC

SELECT EFT.TRANSFER_ID, EFT.APPLY_NUMBER, EFT.COMPANY_ID, EFT.UNIT_ID, EFT.DATA_CLASS, EFT.APPLY_STATUS, v1.meaning APPLY_STATUS_N, EFT.APPLY_DATE, EFT.BUSINESS_TYPE, EFT.DESCRIPTION, FOU.UNIT_NAME, FC.COMPANY_FULL_NAME COMPANY_NAME, SU.DESCRIPTION APPLY_USER_NAME FROM EFT_FUND_TRANSFER EFT JOIN FND_ORG_UNIT FOU ON FOU.UNIT_ID=EFT.UNIT_ID JOIN FND_COMPANY FC ON FC.COMPANY_ID=EFT.COMPANY_ID JOIN SYS_USER SU ON SU.USER_ID=EFT.CREATED_BY left join sys_code_value_b_v v1 on v1.code_value = EFT.APPLY_STATUS and v1.code = 'HLS.WORK_FLOW_STATUS' WHERE 1=1 AND EFT.COMPANY_ID = #{request.companyId}
AND EFT.BUSINESS_TYPE = #{businessType}
AND EFT.DATA_CLASS = #{dataClass}
AND EFT.TRANSFER_ID = #{transferId}
AND EFT.APPLY_DATE >= #{applyDateStart}
AND EFT.APPLY_DATE <= #{applyDateEnd}
AND EFT.APPLY_STATUS = #{applyStatus}
AND SU.DESCRIPTION LIKE CONCAT(CONCAT('%',#{applyUserName}),'%')
ORDER BY EFT.APPLY_DATE DESC
